def normalize_approval_levels(apps, schema_editor):
    ApprovalDocumentLevel = apps.get_model("approval", "ApprovalDocumentLevel")
    ApprovalDocumentCategory = apps.get_model("approval", "ApprovalDocumentCategory")

    review_categories = {
        category.institution_id: category.id
        for category in ApprovalDocumentCategory.objects.filter(
            reference_code__iexact="review",
            institution_id__isnull=False,
            deleted_at__isnull=True,
        )
    }

    approve_categories = {
        category.institution_id: category.id
        for category in ApprovalDocumentCategory.objects.filter(
            reference_code__iexact="approve",
            institution_id__isnull=False,
            deleted_at__isnull=True,
        )
    }

    for institution_id, approve_category_id in approve_categories.items():
        review_category_id = review_categories.get(institution_id)

        if review_category_id is None:
            continue

        document_ids = (
            ApprovalDocumentLevel.objects.filter(
                approval_document__institution_id=institution_id,
                category_id=approve_category_id,
                deleted_at__isnull=True,
            )
            .values_list("approval_document_id", flat=True)
            .distinct()
        )

        for document_id in document_ids.iterator():
            approve_levels = ApprovalDocumentLevel.objects.filter(
                approval_document_id=document_id,
                category_id=approve_category_id,
                deleted_at__isnull=True,
            )

            final_level = approve_levels.aggregate(value=Max("level"))["value"]

            if final_level is None:
                continue

            approve_levels.filter(
                level__lt=final_level,
            ).update(
                category_id=review_category_id,
            )


